iterate.script:
const bomDetailList = bomDetOut.bomDetailList
let allQuantitiesMatch = true
for (const bomDetailMap of bomDetailList) {
    let estConsumeQuantity = toDecimal(0)
    for (const bomProductId of bomDetailMap.productIdSet) {
        estConsumeQuantity = estConsumeQuantity.add(consumeQuantityRemainingMap[bomProductId] ?? 0)
    }

    bomDetailMap.quantityNeeded = toDecimal(bomDetailMap.bomQuantity ?? 1).multiply(produceWepd.estimatedQuantity ?? 0)

    // only use up to quantityNeeded from quantity consumed for product(s)
    if (bomDetailMap.quantityNeeded.compare(estConsumeQuantity) < 0) estConsumeQuantity = bomDetailMap.quantityNeeded

    // reduce consumeQuantityRemainingMap entry(ies) by estConsumeQuantity
    let consumeReduceRemaining = estConsumeQuantity
    for (const bomProductId of bomDetailMap.productIdSet) {
        const remainingForProduct = toDecimal(consumeQuantityRemainingMap[bomProductId] ?? 0)
        const curReduce = remainingForProduct.compare(consumeReduceRemaining) > 0 ? consumeReduceRemaining : remainingForProduct
        consumeReduceRemaining = consumeReduceRemaining.subtract(curReduce)
        consumeQuantityRemainingMap[bomProductId] = remainingForProduct.subtract(curReduce)
        if (consumeReduceRemaining.isZero()) break
    }

    bomDetailMap.estConsumeQuantity = estConsumeQuantity
    bomDetailMap.quantityRemaining = bomDetailMap.quantityNeeded.subtract(estConsumeQuantity)
    if (!bomDetailMap.quantityRemaining.isZero()) allQuantitiesMatch = false
}

if (!(allQuantitiesMatch && excludeWithMatchingConsume)) {
    produceBomDetailList.push({productId:produceWepd.productId, workEffortProductDetail:produceWepd,
            estimatedQuantity:produceWepd.estimatedQuantity, bomDetailList:bomDetailList})
}

actions.script:
const remainingMap = {}
for (const [curProductId, curQuantity] of Object.entries(consumeQuantityRemainingMap)) {
    if (!toDecimal(curQuantity).isZero()) remainingMap[curProductId] = curQuantity
}
consumeQuantityRemainingMap = remainingMap

